xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        W := 0.6;
        N := 6;

        WD := W / N;
        D[0] := -W + 2 * WD;
        for i := 1 to N - 2 do
            D[i] := D[i-1] + 2 * WD;

        WX := WD;
        WY := WD;
        WZ := WD;

        S[0] := ' 1111 |111111|111111|111111|111111| 1111 ';
        S[1] := '111111|100001|100001|100001|100001|111111'; // zeros are to avoid internal coloring
        S[2] := '111111|100001|10  01|10  01|100001|111111';
        S[3] := '111111|100001|10  01|10  01|100001|111111';
        S[4] := '111111|100001|100001|100001|100001|111111';
        S[5] := ' 1111 |111111|111111|111111|111111| 1111 ';

        function GetType(x1, y1, z1);
        begin
            if (x1 < 0) or (y1 < 0) or (z1 < 0) or (x1 >= N) or (y1 >= N) or (z1 >= N) then
                Result := ' '
            else
                Result := copy(S[N-1-z1], (N + 1) * y1 + x1 + 1, 1);
        end;

        procedure CalcCubie(No);
        begin
            x := No mod N;
            y := No div N mod N;
            z := No div N div N;
            for i := 0 to 5 do
                Colors[i] := -1;
            CType := GetType(x,y,z);
            if CType = '1' then begin
                if GetType(x-1,y,z) = ' ' then Colors[0] := clRed;
                if GetType(x+1,y,z) = ' ' then Colors[1] := clOrange;
                if GetType(x,y-1,z) = ' ' then Colors[2] := clBlue;
                if GetType(x,y+1,z) = ' ' then Colors[3] := clGreen;
                if GetType(x,y,z-1) = ' ' then Colors[4] := clYellow;
                if GetType(x,y,z+1) = ' ' then Colors[5] := clWhite;
            end;
            if CType <> ' ' then begin 
                DWX := WD * (2 * x - N + 1);
                DWY := WD * (2 * y - N + 1);
                DWZ := WD * (2 * z - N + 1);
                CCount := 1;
            end else
                CCount := 0;
        end;
